CREATE TABLE seat_inventory(id BIGINT PRIMARY KEY AUTO_INCREMENT,train_id BIGINT NOT NULL,journey_date DATE NOT NULL,coach_code VARCHAR(12) NOT NULL,seat_number VARCHAR(12) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE',version BIGINT NOT NULL DEFAULT 0,UNIQUE KEY uq_inventory_seat(train_id,journey_date,coach_code,seat_number));
CREATE TABLE bookings(id BINARY(16) PRIMARY KEY,booking_reference VARCHAR(24) NOT NULL,customer_id BINARY(16) NOT NULL,train_id BIGINT NOT NULL,journey_date DATE NOT NULL,status VARCHAR(24) NOT NULL,idempotency_key VARCHAR(128) NOT NULL,total_amount DECIMAL(12,2) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY uq_booking_reference(booking_reference),UNIQUE KEY uq_booking_idempotency(customer_id,idempotency_key));
CREATE TABLE booking_seats(booking_id BINARY(16) NOT NULL,inventory_id BIGINT NOT NULL,PRIMARY KEY(booking_id,inventory_id),FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(inventory_id) REFERENCES seat_inventory(id),UNIQUE KEY uq_booking_inventory(inventory_id));
CREATE TABLE outbox_events(event_id BINARY(16) PRIMARY KEY,aggregate_type VARCHAR(80) NOT NULL,aggregate_id VARCHAR(100) NOT NULL,event_type VARCHAR(120) NOT NULL,payload JSON NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),published_at TIMESTAMP(6) NULL,attempts INT NOT NULL DEFAULT 0);
